FROM IO IMPORT Put;
FROM Fmt IMPORT Int;

PROCEDURE Ackermann(m, n: CARDINAL): CARDINAL =
  BEGIN
    IF m = 0 THEN 
      RETURN n + 1;
    ELSIF n = 0 THEN
      RETURN Ackermann(m - 1, 1);
    ELSE
      RETURN Ackermann(m - 1, Ackermann(m, n - 1));
    END;
  END Ackermann;

BEGIN
  FOR m := 0 TO 3 DO
    FOR n := 0 TO 6 DO
      Put(Int(Ackermann(m, n)) & " ");
    END;
    Put("\n");
  END;
END Ack.

MODULE AdditivePrimes EXPORTS Main;

IMPORT SIO,Fmt;

CONST
  Max = 500;

VAR
  Count:CARDINAL := 0;
  Prime:ARRAY[2..Max] OF BOOLEAN;

PROCEDURE DigitSum(N:CARDINAL):CARDINAL =
  BEGIN
    IF N < 10 THEN RETURN N
    ELSE RETURN (N MOD 10) + DigitSum(N DIV 10) END;
  END DigitSum;

PROCEDURE Sieve() =
  VAR J:CARDINAL;
  BEGIN
    FOR I := 2 TO Max DO Prime[I] := TRUE END;
    FOR I := 2 TO Max DIV 2 DO
      IF Prime[I] THEN
        J := I*2;
        WHILE J <= Max DO
          Prime[J] := FALSE;
          INC(J,I)
        END
      END
    END;
  END Sieve;

BEGIN
  Sieve();
  FOR N := 2 TO Max DO
    IF Prime[N] AND Prime[DigitSum(N)] THEN
      SIO.PutText(Fmt.F("%4s",Fmt.Int(N)));
      INC(Count);
      IF Count MOD 10 = 0 THEN SIO.Nl() END
    END
  END;
  SIO.PutText(Fmt.F("\nThere are %s additive primes less than %s.\n",
                    Fmt.Int(Count),Fmt.Int(Max)));
END AdditivePrimes.

MODULE AntiPrimes EXPORTS Main;

IMPORT IO,Fmt;

CONST
  Amount = 20;

VAR
  Max,Seen,N,F:CARDINAL;

PROCEDURE Factors(N:CARDINAL):CARDINAL = 
  VAR
    Facts:CARDINAL;
  BEGIN
    IF N < 2 THEN RETURN 1 END;
    Facts := 2;
    FOR Div := 2 TO N DIV 2 DO
      IF N MOD Div = 0 THEN INC(Facts) END;
    END;
    RETURN Facts;
  END Factors;

BEGIN
  Max := 0;
  Seen := 0;
  N := 1;
  WHILE Seen < Amount DO
    F := Factors(N);
    IF F > Max THEN
      IO.Put(Fmt.F("%5s",Fmt.Int(N)));
      Max := F;
      INC(Seen);
      IF Seen MOD 10 = 0 THEN IO.Put("\n") END;
    END;
    INC(N);
  END;
END AntiPrimes.

