create or replace procedure foursquares(lo number,hi number,uniq boolean,show boolean)
as
    a number;
    b number;
    c number;
    d number;
    e number;
    f number;
    g number;
    out_line varchar2(2000);

    cursor results_cur is 
    select
       a,
       b,
       c,
       d,
       e,
       f,
       g
    from
        results
    order by 
        a,b,c,d,e,f,g;

    results_rec results_cur%rowtype;

    solutions number;
    uorn varchar2(2000);
begin
    solutions := 0;
    delete from allints;
    delete from results;
    for i in lo..hi loop
        insert into allints values (i);
    end loop;
    commit;

    if uniq = TRUE then
        insert into results
            select
                a.v a,
                b.v b,
                c.v c,
                d.v d,
                e.v e,
                f.v f,
                g.v g
            from
                allints a, allints b, allints c,allints d,
                allints e, allints f, allints g
            where
                a.v not in (b.v,c.v,d.v,e.v,f.v,g.v) and
                b.v not in (c.v,d.v,e.v,f.v,g.v) and
                c.v not in (d.v,e.v,f.v,g.v) and
                d.v not in (e.v,f.v,g.v) and
                e.v not in (f.v,g.v) and
                f.v not in (g.v) and
                a.v = c.v + d.v and
                g.v = d.v + e.v and
                b.v = e.v + f.v - c.v
            order by 
                a,b,c,d,e,f,g;
        uorn := ' unique solutions in ';
    else
        insert into results
            select
                a.v a,
                b.v b,
                c.v c,
                d.v d,
                e.v e,
                f.v f,
                g.v g
            from
                allints a, allints b, allints c,allints d,
                allints e, allints f, allints g
            where
                a.v = c.v + d.v and
                g.v = d.v + e.v and
                b.v = e.v + f.v - c.v
            order by 
                a,b,c,d,e,f,g;   
        uorn := ' non-unique solutions in ';
    end if;
    commit;

    open results_cur;
    loop
        fetch results_cur into results_rec;
        exit when results_cur%notfound;
        a := results_rec.a;
        b := results_rec.b;
        c := results_rec.c;
        d := results_rec.d;
        e := results_rec.e;
        f := results_rec.f;
        g := results_rec.g;

        solutions := solutions + 1;
        if show = TRUE then
            out_line := to_char(a) || ' ';
            out_line := out_line || ' ' || to_char(b) || ' ';
            out_line := out_line || ' ' || to_char(c) || ' ';
            out_line := out_line || ' ' || to_char(d) || ' ';
            out_line := out_line || ' ' || to_char(e) || ' ';
            out_line := out_line || ' ' || to_char(f) ||' ';
            out_line := out_line || ' ' || to_char(g);
        end if;

        dbms_output.put_line(out_line);
    end loop;
    close results_cur;
    out_line := to_char(solutions) || uorn;
    out_line := out_line || to_char(lo) || ' to ' || to_char(hi);
    dbms_output.put_line(out_line);

end;
/

DECLARE

  FUNCTION ackermann(pi_m IN NUMBER,
                     pi_n IN NUMBER) RETURN NUMBER IS
  BEGIN
    IF pi_m = 0 THEN
      RETURN pi_n + 1;
    ELSIF pi_n = 0 THEN
      RETURN ackermann(pi_m - 1, 1);
    ELSE
      RETURN ackermann(pi_m - 1, ackermann(pi_m, pi_n - 1));
    END IF;
  END ackermann;

BEGIN
  FOR n IN 0 .. 6 LOOP
    FOR m IN 0 .. 3 LOOP
      dbms_output.put_line('A(' || m || ',' || n || ') = ' || ackermann(m, n));
    END LOOP;
  END LOOP;
END;

-- Let's create a generic class with one method to be used as an interface:
create or replace
TYPE callback AS OBJECT (
    -- A class needs at least one member even though we don't use it
    -- There's no generic OBJECT type, so let's call it NUMBER
    dummy NUMBER,
    -- Here's our function, and since PL/SQL doesn't have generics,
    -- let's use type NUMBER for our params
    MEMBER FUNCTION exec(n number) RETURN number
) NOT FINAL not instantiable;
/

-- Now let's inherit from that, defining a class with one method. We'll have ours square a number.
-- We can pass this class into any function that takes type callback:
CREATE OR REPLACE TYPE CB_SQUARE under callback (
    OVERRIDING MEMBER FUNCTION exec(n NUMBER) RETURN NUMBER
)
/
CREATE OR REPLACE
TYPE BODY CB_SQUARE AS
    OVERRIDING MEMBER FUNCTION exec(n NUMBER) RETURN NUMBER IS
    BEGIN
        RETURN n * n;
    END exec;
END;
/

-- And a package to hold our test
CREATE OR REPLACE 
PACKAGE PKG_CALLBACK AS 
    myCallback cb_square;
    TYPE intTable IS TABLE OF NUMBER INDEX BY BINARY_INTEGER;
    ints intTable;
    i PLS_INTEGER;

    procedure test_callback;
END PKG_CALLBACK;
/

CREATE OR REPLACE PACKAGE BODY PKG_CALLBACK AS
    -- Our generic mapping function that takes a "method" and a collection
    -- Note that it takes the generic callback type 
    -- that doesn't know anything about squaring
    procedure do_callback(myCallback IN callback, ints IN OUT intTable) IS
        i PLS_INTEGER;
        myInt NUMBER;
    begin
        for i in 1 .. ints.count loop
            myInt := ints(i);
            -- PL/SQL call's the child's method
            ints(i) := myCallback.exec(myInt);
        END LOOP;
    end do_callback;

    procedure test_callback IS
    BEGIN
        myCallback := cb_square(null);
        FOR i IN 1..5 LOOP
            ints(i) := i;
        END LOOP;

        do_callback(myCallback, ints);

        i := ints.FIRST;
        WHILE i IS NOT NULL LOOP
            DBMS_OUTPUT.put_line(ints(i));
            i := ints.next(i);
        END LOOP;
    END test_callback;
END PKG_CALLBACK;
/

BEGIN
  PKG_CALLBACK.TEST_CALLBACK();
END;
/

