enum Classification {
  DEFICIENT,
  PERFECT,
  ABUNDANT
}

void main() {
  var i = 0; var j = 0;
  var sum = 0; var try_max = 0;
  int[] count_list = {1, 0, 0};
  for (i = 2; i <= 20000; i++) {
    try_max = i / 2;
    sum = 1;
    for (j = 2; j < try_max; j++) {
      if (i % j != 0)
        continue;
      try_max = i / j;
      sum += j;
      if (j != try_max)
        sum += try_max;
    }
    if (sum < i) {
      count_list[Classification.DEFICIENT]++;
      continue;
    }
    if (sum > i) {
      count_list[Classification.ABUNDANT]++;
      continue;
    }
    count_list[Classification.PERFECT]++;
  }
  print(@"There are $(count_list[Classification.DEFICIENT]) deficient,");
  print(@" $(count_list[Classification.PERFECT]) perfect,");
  print(@" $(count_list[Classification.ABUNDANT]) abundant numbers between 1 and 20000.\n");
}

uint64 ackermann(uint64 m, uint64 n) {
  if (m == 0) return n + 1;
  if (n == 0) return ackermann(m - 1, 1);
  return ackermann(m - 1, ackermann(m, n - 1));
}

void main () {
  for (uint64 m = 0; m < 4; ++m) {
    for (uint64 n = 0; n < 10; ++n) {
      print(@"A($m,$n) = $(ackermann(m,n))\n");
    }
  }
}

using Math;
using Posix;
using Gee;

class VAnaPrimes {
	static bool isPrime(int n) {
		int Limit = (int)Math.trunc(Math.sqrt(n));
		int i = 5;
		if (n == 1) { return false; }
		if (n % 2 == 0) { return n == 2; }
		if (n % 3 == 0) { return n == 3; }
		while (i <= Limit) {
			if (n % i == 0) { return false; }
			i = i + 2;
			if (n % i == 0) { return false; }
			i = i + 4;
		}
		return true;
	}

	static int charcmp(ref char a, ref char b){
		return (int)(a > b) - (int)(a < b);
	}

	static int intcmp(ref int x, ref int y) {
		return x - y;
	}

	static void get_anaprimes_in_range(int from, int to) {
		var ranks = new Gee.HashMultiMap<string,int>();
		int  max = 0;
		for (int i = from; i <= to; i++) {
			if (isPrime(i)) {
				string str = i.to_string();
				Posix.qsort(str,str.length,sizeof(char),(Posix.compar_fn_t)charcmp);
				ranks[str] = i;
				max = max > ranks[str].size ? max : ranks[str].size;
			}
		}
		printf(" max numbers %d\n",max);
		var iter = ranks.get_keys().iterator();
		while (iter.next()) {
			int[] items = ranks[iter.get()].to_array();
			if (items.length == max) {
				Posix.qsort(items,items.length,sizeof(int),(Posix.compar_fn_t)intcmp);
				printf("\t%d ... %d\n",items[0],items[items.length - 1]);
			}
		}
	}

	public static void main (string[] args) {
