    if .board == .goal then "Congratulations. You solved the puzzle in \(.n) moves."
    else
      "Enter move #\(.n + 1) (u, d, l, r or q): ",
      ( (limit(1;inputs)[:1]|ascii_downcase) as $m
        | if $m == "q" then halt
          else isValidMove($m) as $p
          | if $p then move($p) | prompt
