# The following may be omitted if using the C implementation
# or if the debug messages are deleted.
def debug(msg): (msg | tostring | debug | empty), .;

### Generic functions

def array_swap($i; $j):
  if $j < $i then array_swap($j;$i)
  elif $i == $j then .
  else .[:$i] + [.[$j]] + .[$i+1:$j] + [.[$i]] + .[$j+1:]
